class Solution {
public:
    std::string tictactoe(std::vector<std::vector<int>>& moves) {
        std::vector<int> rows(3, 0), cols(3, 0);
        int diag = 0, antiDiag = 0;

        for (int i = 0; i < moves.size(); ++i) {
            int r = moves[i][0], c = moves[i][1];
            int val = (i % 2 == 0 ? 1 : -1);
            rows[r] += val;
            cols[c] += val;
            if (r == c) diag += val;
            if (r + c == 2) antiDiag += val;

            if (std::abs(rows[r]) == 3 || std::abs(cols[c]) == 3 || std::abs(diag) == 3 || std::abs(antiDiag) == 3) {
                return val == 1 ? "A" : "B";
            }
        }
        return moves.size() == 9 ? "Draw" : "Pending";
    }
};

class Solution {
    public String tictactoe(int[][] moves) {
        int[] rows = new int[3];
        int[] cols = new int[3];
        int diag = 0, antiDiag = 0;

        for (int i = 0; i < moves.length; i++) {
            int r = moves[i][0], c = moves[i][1];
            int val = (i % 2 == 0 ? 1 : -1);
            rows[r] += val;
            cols[c] += val;
            if (r == c) diag += val;
            if (r + c == 2) antiDiag += val;

            if (Math.abs(rows[r]) == 3 || Math.abs(cols[c]) == 3 || Math.abs(diag) == 3 || Math.abs(antiDiag) == 3) {
